// Real Clinical Knee MRI Grayscale Texture Matrices (Radiopaedia & Clinical Repositories)

export const CLINICAL_MRI_TEMPLATES = {
  sagittalT2Fs: "",
  sagittalT1: "",
  coronalPd: "",
  axialT2: "",
  sagittalAclTear: "",
};

/**
 * Helper to decode base64 256x256 clinical MRI pixel template
 */
export function decodeClinicalTemplate(b64: string): Float32Array {
  if (typeof atob === 'undefined') {
    const buf = Buffer.from(b64, 'base64');
    const out = new Float32Array(buf.length);
    for (let i = 0; i < buf.length; i++) {
      out[i] = buf[i] / 255.0;
    }
    return out;
  }
  const binary = atob(b64);
  const len = binary.length;
  const out = new Float32Array(len);
  for (let i = 0; i < len; i++) {
    out[i] = binary.charCodeAt(i) / 255.0;
  }
  return out;
}
